steps.script:
var st = GameState.state
var g = st.units.U_CUSTODIAN_GUARD_B
var k = 0
for m in g.models:
	m.position = {"x": 1430.0 + float(k) * 65.0, "y": 400.0}
	k += 1
if g.has("flags"):
	g.flags.erase("last_shot_idx")
	g.flags.erase("shot_recently")
var s = st.units.U_CUSTODIAN_GUARD_A_P2
var j = 0
for m in s.models:
	m.position = {"x": 1440.0 + float(j) * 65.0, "y": 1560.0}
	j += 1
var p1 = 0
var p2 = 0
for uid in st.units:
	if uid == "U_CUSTODIAN_GUARD_B" or uid == "U_CUSTODIAN_GUARD_A_P2":
		continue
	var u = st.units[uid]
	for m in u.get("models", []):
		if m.get("position") == null:
			continue
		if int(u.get("owner", 0)) == 1:
			m.position = {"x": 50.0 + 70.0 * float(p1 % 6), "y": 50.0 + 70.0 * float(p1 / 6)}
			p1 += 1
		else:
			m.position = {"x": 1300.0 + 70.0 * float(p2 % 6), "y": 2320.0 - 70.0 * float(p2 / 6)}
			p2 += 1
return TerrainManager.area_at(Vector2(1500.0, 750.0)).get("id", "")

# FIX_MOVE_COVER ships OFF: load the opt-in profile AFTER configure()
# (configure wipes profiles).
var f = FileAccess.open("res://tests/bench_profiles/move_cover_on.json", FileAccess.READ)
var prof = JSON.parse_string(f.get_as_text())
f.close()
AIDecisionMaker.load_player_profile(1, prof)
return prof.parameters.size()

var d = AIPlayer.request_suggestion("U_CUSTODIAN_GUARD_B")
var u = GameState.state.units.U_CUSTODIAN_GUARD_B
var dests = d.get("_ai_model_destinations", {})
var n = 0
for m in u.models:
	if not m.get("alive", true) or not dests.has(m.id):
		continue
	var probe = m.duplicate(true)
	probe["position"] = {"x": float(dests[m.id][0]), "y": float(dests[m.id][1])}
	if TerrainManager.is_model_hidden(probe, u):
		n += 1
return n

# SHIPPED-DEFAULT CHECK: clearing the profile leaves FIX_MOVE_COVER at 0 —
# the straight move, no note, the 5th model outside the ruin.
AIDecisionMaker.clear_player_profile(1)
var d = AIPlayer.request_suggestion("U_CUSTODIAN_GUARD_B")
var u = GameState.state.units.U_CUSTODIAN_GUARD_B
var dests = d.get("_ai_model_destinations", {})
var n = 0
for m in u.models:
	if not m.get("alive", true) or not dests.has(m.id):
		continue
	var probe = m.duplicate(true)
	probe["position"] = {"x": float(dests[m.id][0]), "y": float(dests[m.id][1])}
	if TerrainManager.is_model_hidden(probe, u):
		n += 1
return (not str(d.get("_ai_move_adjustments", [])).contains("Hidden next turn from")) and n == 4 and str(d.get("_ai_description", "")).contains("moves toward obj_nml_1")

# ...and reloading the profile restores the spot.
var f = FileAccess.open("res://tests/bench_profiles/move_cover_on.json", FileAccess.READ)
var prof = JSON.parse_string(f.get_as_text())
f.close()
AIDecisionMaker.load_player_profile(1, prof)
var d = AIPlayer.request_suggestion("U_CUSTODIAN_GUARD_B")
var u = GameState.state.units.U_CUSTODIAN_GUARD_B
var dests = d.get("_ai_model_destinations", {})
var n = 0
for m in u.models:
	if not m.get("alive", true) or not dests.has(m.id):
		continue
	var probe = m.duplicate(true)
	probe["position"] = {"x": float(dests[m.id][0]), "y": float(dests[m.id][1])}
	if TerrainManager.is_model_hidden(probe, u):
		n += 1
return n == 5 and str(d.get("_ai_move_adjustments", [])).contains("Hidden next turn from")

# The AI's own execution path: stage + confirm through AIPlayer, then ask
# the ENGINE where the models are.
var d = AIPlayer.request_suggestion("U_CUSTODIAN_GUARD_B")
NetworkIntegration.route_action({"type": "BEGIN_NORMAL_MOVE", "actor_unit_id": "U_CUSTODIAN_GUARD_B", "player": 1})
var ph = PhaseManager.current_phase_instance
if ph.has_method("has_pending_stratagem_window") and ph.has_pending_stratagem_window():
	var w = ph.get_pending_stratagem_window()
	NetworkIntegration.route_action({"type": "DECLINE_WINDOW_STRATAGEM", "player": int(w.get("player", 1)), "window_id": str(w.get("window_id", ""))})
AIPlayer._execute_ai_movement(1, d)
var u = GameState.state.units.U_CUSTODIAN_GUARD_B
var obj = {}
for o in GameState.state.board.objectives:
	if str(o.get("id", "")) == "obj_nml_1":
		obj = o
var hidden = 0
var on_obj = 0
for m in u.models:
	if not m.get("alive", true):
		continue
	if TerrainManager.is_model_hidden(m, u):
		hidden += 1
	if MissionManager.model_in_objective_range(m, obj):
		on_obj += 1
return bool(u.get("flags", {}).get("moved", false)) and hidden == 5 and on_obj >= 1 and TerrainManager.unit_has_cover_11e(u, {})

# A legal target exists (so the hold-fire below is a choice, not a
# no-target pass): the enemy squad 23" away is in range and visible.
var snap = GameState.create_snapshot()
return RulesEngine.get_eligible_targets("U_CUSTODIAN_GUARD_B", snap, true).size()

# F002 cooperation: Hidden squad, chip shot only — it holds fire rather
# than shooting its Hidden away for this turn and the next.
AIDecisionMaker.reset_caches()
var snap = GameState.create_snapshot()
var dd = AIDecisionMaker.decide(8, snap, [{"type": "SELECT_SHOOTER", "actor_unit_id": "U_CUSTODIAN_GUARD_B"}], 1)
return str(dd.get("type", ""))

# CONTROL: with the profile cleared (shipped defaults, F002 off) the same
# decision shoots — the hold-fire above is the profile, nothing else.
AIDecisionMaker.clear_player_profile(1)
AIDecisionMaker.reset_caches()
var snap = GameState.create_snapshot()
var dd = AIDecisionMaker.decide(8, snap, [{"type": "SELECT_SHOOTER", "actor_unit_id": "U_CUSTODIAN_GUARD_B"}], 1)
var f = FileAccess.open("res://tests/bench_profiles/move_cover_on.json", FileAccess.READ)
var prof = JSON.parse_string(f.get_as_text())
f.close()
AIDecisionMaker.load_player_profile(1, prof)
return str(dd.get("type", ""))
